import{_ as e,a0 as x,w as a,s as r,I as n,x as o,a1 as i,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Fotoxx：用于管理和编辑大型照片集合的开源应用 | LCTT x X-CMD","titleTemplate":false,"description":"Fotoxx：用于管理和编辑大型照片集合的开源应用 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fotoxx：用于管理和编辑大型照片集合的开源应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fotoxx：用于管理和编辑大型照片集合的开源应用 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210629 Fotoxx- An Open Source App for Managing and Editing Large Photo Collection","title":"Fotoxx：用于管理和编辑大型照片集合的开源应用","tag":"202107","desc":""},"relativePath":"202107/20210629 Fotoxx- An Open Source App for Managing and Editing Large Photo Collection.md","filePath":"[post].md"}'),u={name:"202107/20210629 Fotoxx- An Open Source App for Managing and Editing Large Photo Collection.md"};function f(d,t,g,m,T,C){const s=x("Link");return a(),r("div",null,[t[24]||(t[24]=n("h1",{id:"fotoxx-用于管理和编辑大型照片集合的开源应用",tabindex:"-1"},[o("Fotoxx：用于管理和编辑大型照片集合的开源应用 "),n("a",{class:"header-anchor",href:"#fotoxx-用于管理和编辑大型照片集合的开源应用","aria-label":"Permalink to “Fotoxx：用于管理和编辑大型照片集合的开源应用”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202107/07/131024ej2kzv824zqb4zz8.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=o("说到 ",-1)),i(s,{href:"https://itsfoss.com/linux-photo-management-software/"},{default:p(()=>[...t[0]||(t[0]=[o("Linux 中的照片管理软件",-1)])]),_:1}),t[2]||(t[2]=o("，Shotwell 可能是其中最有名的。难怪它在许多发行版中都预装了。",-1))]),t[26]||(t[26]=l('<p>但是，如果你正在寻找一个类似 Shotwell 而速度更快的应用，Fotoxx 可能是一个不错的选择。</p><p>它可能没有一个现代的用户界面，但它在处理大量照片集合时速度很快。这一点很重要，因为索引和显示成千上万张照片的缩略图可能需要相当多的时间和计算资源。</p><h3 id="用-fotoxx-在-linux-中管理照片并编辑它们" tabindex="-1">用 Fotoxx 在 Linux 中管理照片并编辑它们 <a class="header-anchor" href="#用-fotoxx-在-linux-中管理照片并编辑它们" aria-label="Permalink to “用 Fotoxx 在 Linux 中管理照片并编辑它们”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/06/fotoxx-interface.jpg?resize=800%2C561&amp;ssl=1" alt="Fotoxx interface"></p><p>正如你在上面的截图中看到的，它没有漂亮的界面。看起来更像是一个 2010 年左右的应用。它在视觉上的不足，在功能和性能上得到了弥补。</p><p>你可以导入大量的照片，包括 RAW 图像。这些图片保持原样。它们不会被复制或移动。它们只是在应用中被索引。</p><p>你可以编辑图像元数据，如标签、地理标签、日期、评级、标题等。你可以根据这些元数据来搜索图片。</p><p>它还有一个地图功能，可以分组并显示属于某个地点的图片（基于图片上的地理标签数据）。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/06/fotoxx-geotag-map-view.jpg?resize=800%2C466&amp;ssl=1" alt="Map view"></p><p>由于它专注于管理大型照片集合，有几个批处理功能，可以重命名、调整大小、复制/移动、转换图像格式和编辑元数据。</p><p>你可以选择图片来创建相册和幻灯片，所有这些都是在去重图片的情况下进行的。照片可以组合成 360 度的全景图。</p><p>Fotoxx 还有几个编辑功能，可以用来修饰图片，添加效果（如素描、绘画）、修剪、旋转等。</p><p>还有一些选项可以去除旧的、扫描照片打印件上的红眼和尘斑。</p>',13)),n("p",null,[t[4]||(t[4]=o("我可以继续列举功能清单，但这太长了。它的网站描述了它的",-1)),i(s,{href:"https://kornelix.net/fotoxx/fotoxx.html"},{default:p(()=>[...t[3]||(t[3]=[o("全部功能",-1)])]),_:1}),t[5]||(t[5]=o("，你应该去看看。",-1))]),t[27]||(t[27]=l('<h3 id="在-linux-上安装-fotoxx" tabindex="-1">在 Linux 上安装 Fotoxx <a class="header-anchor" href="#在-linux-上安装-fotoxx" aria-label="Permalink to “在 Linux 上安装 Fotoxx”">​</a></h3><p>请记住，<strong>Fotoxx 的开发者建议使用一台强大的计算机</strong>，有 4 个以上的 CPU 核心，16GB 以上的内存，以便正常运行。较小的计算机可能会很慢，或可能无法编辑大型图像。</p><p>Fotoxx 在大多数 Linux 发行版中都有，如 Debian、Ubuntu、Fedora 和 Arch Linux。只需使用你的发行版的包管理器或软件中心来搜索 Fotoxx 并安装它。</p><p>在基于 Ubuntu 和 Debian 的发行版上，你可以使用 apt 命令来安装它，像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fotoxx</span></span></code></pre></div><p>当你第一次运行它时，它会要求搜索主目录中的图像。你可以继续使用它，或者将搜索位置限制在选定的文件夹。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/06/fotoxx-indexing.png?resize=800%2C617&amp;ssl=1" alt=""></p><p>我注意到，尽管在一分钟左右的时间内索引了 4700 多张，但它并没有立即开始显示图片。我不得不<strong>点击 Gallery-&gt;All Folders，然后选择文件夹，然后它就显示了图片</strong>。所以，这一点要记住。</p>',8)),n("p",null,[t[7]||(t[7]=o("Fotoxx 是一个功能广泛的工具，你需要一些时间来适应它并探索它的",-1)),i(s,{href:"https://kornelix.net/fotoxx/fotoxx.html"},{default:p(()=>[...t[6]||(t[6]=[o("所有功能",-1)])]),_:1}),t[8]||(t[8]=o("。它的网站列出了几个例子，你应该看看。",-1))]),t[28]||(t[28]=n("p",null,"正如我前面所说，它不是最漂亮的应用，但它大量的功能列表可以完成任务。如果你是一个摄影师或有大量的图片收藏，你可以试试 Fotoxx，看看它是否符合你的需要。当你试过后，请在评论区分享你的经验。",-1)),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=o("via: ",-1)),i(s,{href:"https://itsfoss.com/fotoxx/"},{default:p(()=>[...t[9]||(t[9]=[o("https://itsfoss.com/fotoxx/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=o("作者：",-1)),i(s,{href:"https://itsfoss.com/author/abhishek/"},{default:p(()=>[...t[11]||(t[11]=[o("Abhishek Prakash",-1)])]),_:1}),t[16]||(t[16]=o(" 选题：",-1)),i(s,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[12]||(t[12]=[o("lujun9972",-1)])]),_:1}),t[17]||(t[17]=o(" 译者：",-1)),i(s,{href:"https://github.com/geekpi"},{default:p(()=>[...t[13]||(t[13]=[o("geekpi",-1)])]),_:1}),t[18]||(t[18]=o(" 校对：",-1)),i(s,{href:"https://github.com/wxy"},{default:p(()=>[...t[14]||(t[14]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原创编译，",-1)),i(s,{href:"https://linux.cn/"},{default:p(()=>[...t[20]||(t[20]=[o("Linux中国",-1)])]),_:1}),t[23]||(t[23]=o(" 荣誉推出",-1))])])}const L=e(u,[["render",f]]);export{k as __pageData,L as default};
